UPDATE lessons SET title='Year 4, Week 17, Lesson 2: Communication games', data=json_patch(data,'{"child_mission":"Communication games build listening accuracy: follow multi-step instructions, pass messages carefully and check understanding.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWhy should the speaker check understanding before a team starts a task?\n\nFEEDBACK\nTo catch missed steps and prevent conflict.\n\nWATCH FOR\nBlaming listeners only ignores unclear instructions.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nPlay two communication games. Note one speaking tip and one listening tip that improved success.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"Communication games build listening accuracy: follow multi-step instructions, pass messages carefully and check understanding.","lesson_number":2,"lesson_role":"Practise and apply","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-RRS-01"],"parent_notes":"Parent: Marking guidance for the independent task: Play two communication games. Note one speaking tip and one listening tip that improved success. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using game on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Blaming listeners only ignores unclear instructions.. Correction: To catch missed steps and prevent conflict.. Why it helps the audience is stated.\n\nParent: Likely misconception: Blaming listeners only ignores unclear instructions. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating game on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with game, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about game with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for game. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":1,"explanation":"This matches the taught method for game. The other choices miss a key step or use a common mistake.","options":["A method that skips the key step taught in this lesson","To catch missed steps and prevent conflict","Blaming listeners only ignores unclear instructions","A claim that names no evidence from the lesson material"],"question":"Why should the speaker check understanding before a team starts a task?","type":"multiple_choice"},{"correct_index":3,"explanation":"This is the misconception to avoid for game; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Communication games build listening accuracy: follow multi-step instructions, pass messages carefully and check","To catch missed steps and prevent conflict","Careful use of listen and explain why it matters with clear evidence","Blaming listeners only ignores unclear instructions"],"question":"Which statement is a common mistake when working with game?","type":"multiple_choice"},{"correct_index":2,"explanation":"Understanding is shown by new evidence and a named listen and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Blaming listeners only ignores unclear instructions","Name listen and explain why it matters only, without linking it to game","Apply game to new material and name the listen and explain why it matters used","Repeat the worked example wording with no new evidence"],"question":"Which response best applies game with new evidence?","type":"multiple_choice"},{"correct_index":1,"explanation":"The stronger choice uses safe, healthy or respectful choices appropriately for this lesson on game. The other choices miss a key step or use a common mistake.","options":["Blaming listeners only ignores unclear instructions","To catch missed steps and prevent conflict","Choose the fastest option even when it ignores safety","Use a put-down and call it honesty"],"question":"Which response best uses safe, healthy or respectful choices for game?","type":"multiple_choice"},{"correct_index":0,"explanation":"Strong answers name specific evidence and what it shows. The other choices miss a key step or use a common mistake.","options":["Name a body cue, safety rule or wellbeing strategy and say how it helps with game","Choose the fastest option even when it ignores safety","Use a put-down and call it honesty","Blaming listeners only ignores unclear instructions"],"question":"Which evidence move best supports a claim about game?","type":"multiple_choice"},{"correct_index":2,"explanation":"The stronger choice matches the taught idea (Communication games build listening accuracy: follow multi-step) with concrete detail. The other choices miss a key step or use a common mistake.","options":["Choose the fastest option even when it ignores safety","Use a put-down and call it honesty","Example: telephone with kindness rules","Blaming listeners only ignores unclear instructions"],"question":"Which choice best applies this lesson idea about game?","type":"multiple_choice"},{"correct_index":2,"explanation":"Accuracy means checking evidence and honouring limits or protocols. The other choices miss a key step or use a common mistake.","options":["Ignore safety or cultural protocols to finish faster","Treat every claim as equally reliable without checking a source or cue","Check safety and fairness, include others, and explain the healthier choice","Invent missing details to make the answer sound complete"],"question":"Which action keeps safe, healthy or respectful choices accurate for game?","type":"multiple_choice"},{"correct_index":1,"explanation":"Independence requires a new example that still uses the taught skill. The other choices miss a key step or use a common mistake.","options":["Name listen and explain why it matters only, with no linked example","Play two communication games","Retype the worked example with no new example","Blaming listeners only ignores unclear instructions"],"question":"Which independent response best applies game to new material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about game with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating game on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using game on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for game. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with game, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: Blaming listeners only ignores unclear instructions.. Correction: To catch missed steps and prevent conflict.. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested. Share only what you feel comfortable sharing.","review_status":"unreviewed","seed_key":"s2-pdhpe-y4-w17-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA PDHPE alignment using catalogue outcome codes (PH2-*); content-point mapping remains pending human review. Physical activities are optional, adult-supervised and adaptable; no child is required to share personal details.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise game.","Read the mission before you start moving or deciding.","Keep your own safety and everyone''s inclusion in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reasons with the feedback.","Adjust anything that does not keep everyone safe and included."],"learn":["Study how the first demonstration is built.","Point to the cue or rule that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore safety, consent or inclusion.","Prefer a reasoned, respectful choice over one that merely looks fun."],"submit":["Confirm that your reasons and reflection are both present.","Proofread names, steps and safety words.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked example.","Name one exact cue, rule or choice before you decide.","Think through the small prompt before opening the comparison."],"teach1":["Return to the example and list the key cues.","Say what each cue does for safety, health or friendship.","A final label alone is weaker than a stated reason."],"teach2":["Compare an unsafe or unkind choice with a better one.","Change the choice or strategy, not only the words.","Name the mistake you are repairing."],"teach3":["Choose a fresh place, game or situation that still uses the same skill.","Write one reason in your own words.","Do not retype the worked example as your answer."],"write":["Follow every part of the independent instructions.","Include original reasons and a short reflection.","Save work that shows the skill in a new situation."]},"subject":"Health, Wellbeing and Relationships","success_criteria":["I can use game with a specific example from this lesson.","I can identify listen and explain why it matters.","I can practise instruction independently on a new prompt.","I can notice team needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"Communication games build listening accuracy: follow multi-step instructions, pass messages carefully and check understanding.","options":["Communication games build listening accuracy: follow multi-step instructions, pass messages carefully and check","A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason"],"question":"Which choice best applies this lesson idea about game with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: telephone with kindness rules; instruction obstacle course with one speaker.\n\nTRY FIRST\nWhy should the speaker check understanding before a team starts a task?\n\nFEEDBACK\nTo catch missed steps and prevent conflict.","explain":"Communication games build listening accuracy: follow multi-step instructions, pass messages carefully and check understanding.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Blaming listeners only ignores unclear instructions. Change the choice or strategy, not just the wording.","title":"Understand and demonstrate","visual":[{"alt":"Communication games.","caption":"Clear speak + listen.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Instructions</text><text x=\"28\" y=\"78\">check understanding</text><text x=\"358\" y=\"42\">Games</text><text x=\"358\" y=\"78\">accurate listen</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which cue or rule matters most.","who":"pip"},{"text":"Name the cues, rules or choices that keep everyone safe and included before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this example: Example: telephone with kindness rules; instruction obstacle course with one speaker. Then write your own reasons.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which cue or rule matters most.\nJuno: Name the cues, rules or choices that keep everyone safe and included before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this example: Example: telephone with kindness rules; instruction obstacle course with one speaker. Then write your own reasons."}}]},{"check":{"correct_index":0,"explanation":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.","options":["Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or","A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason"],"question":"Which choice best applies this lesson idea about game with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: telephone with kindness rules; instruction obstacle course with one speaker. Look at each cue, rule or choice that carries the idea.\n\nTRY FIRST\nList the key cues, rules or choices from the example and say what each one does for safety, health or relationships.\n\nFEEDBACK\nThe most useful reasoning names the cue, rule or strategy and the reason it helps, not only a label such as \"good\".","explain":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Writing only a final label without a reason does not show PDHPE thinking. Change the choice or strategy, not just the wording.","title":"Show the reasoning","visual":[{"alt":"Game tips.","caption":"Success tip.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Two games</text><text x=\"28\" y=\"78\">tips</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">blame listeners only</text></g></svg>"}]},{"check":{"correct_index":2,"explanation":"Use an intentionally unsafe or unhelpful choice as a comparison.","options":["A guess with no reason","A choice unrelated to safety, health or respect","Use an intentionally unsafe or unhelpful choice as a comparison","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about game with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nBlaming listeners only ignores unclear instructions. Here is a more helpful example: Example: telephone with kindness rules; instruction obstacle course with one speaker.\n\nTRY FIRST\nDescribe why the warned-against choice does not work, then write a safer, kinder or healthier choice with a reason.\n\nFEEDBACK\nTo catch missed steps and prevent conflict.","explain":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Changing the wording without changing the choice does not fix the error. Blaming listeners only ignores unclear instructions. Change the choice or strategy, not just the wording.","title":"Test a misconception"},{"check":{"correct_index":1,"explanation":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example.","options":["An answer copied without understanding","Use the same PDHPE idea in a new place, game or situation, not a copy of the example","A guess with no reason","A choice unrelated to safety, health or respect"],"question":"Which choice best applies this lesson idea about game with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nCommunication games build listening accuracy: follow multi-step instructions, pass messages carefully and check understanding. Now choose a different situation to show you can transfer the idea.\n\nTRY FIRST\nDescribe or practise one fresh situation that uses the same skill and write a short reason for your choice.\n\nFEEDBACK\nThe new situation should use the same PDHPE idea as the example, but happen in a different place or with different people.","explain":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to a new situation. Change the choice or strategy, not just the wording.","title":"Transfer to a new situation"}],"title":"Year 4, Week 17, Lesson 2: Communication games","unit_number":4,"unit_title":"Relationships, communication and respect","week":17,"week_in_unit":2,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample: telephone with kindness rules; instruction obstacle course with one speaker.\n\nWrite what makes this example safe, healthy or respectful, naming the cues, rules or choices used.","worked_visuals":[{"alt":"Communication games.","caption":"Clear speak + listen.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Instructions</text><text x=\"28\" y=\"78\">check understanding</text><text x=\"358\" y=\"42\">Games</text><text x=\"358\" y=\"78\">accurate listen</text></g></svg>"},{"alt":"Game tips.","caption":"Success tip.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Two games</text><text x=\"28\" y=\"78\">tips</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">blame listeners only</text></g></svg>"}],"year_level":"Year 4"}') WHERE seed_key='s2-pdhpe-y4-w17-l2' AND family_id IS NULL;
